<?php require 'config.php'; require_login(); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); try{$no='RM-'.date('YmdHis').'-'.random_int(10,99);$s=db()->prepare('INSERT INTO patients(medical_record_no,nik,full_name,birth_date,gender,phone,address,registered_branch_id,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$no,trim($_POST['nik']??'')?:null,trim($_POST['full_name']),$_POST['birth_date']?:null,$_POST['gender']?:null,trim($_POST['phone']??''),trim($_POST['address']??''),user()['branch_id'],user()['id']]);flash('Pasien berhasil didaftarkan. Nomor rekam medis: '.$no);redirect('patients.php');}catch(Throwable $e){$error='Gagal menyimpan. NIK mungkin sudah terdaftar.';}}
